async function loadHasher(useFast: boolean) {
    if (useFast) {
        const { createHash } = await import("node:crypto")
        return (s: string) => createHash("md5").update(s).digest("hex").slice(0, 8)
    }
    return (s: string) => [...s].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 0).toString(16)
}

async function main() {
    console.log("crypto:", (await loadHasher(true))("salom"))
    console.log("oddiy:", (await loadHasher(false))("salom"))
}
main()

