import ts from "typescript"

const source = `
enum Color { Red, Green }
namespace Utils { export const PI = 3.14 }
class User { constructor(public name: string) {} }
export { Color, Utils, User }
`
const host = ts.createCompilerHost({})
const getSourceFile = host.getSourceFile
host.getSourceFile = (f, lang) => (f === "/app/main.ts" ? ts.createSourceFile(f, source, lang) : getSourceFile(f, lang))
host.fileExists = (f) => f === "/app/main.ts"

for (const erasableSyntaxOnly of [false, true]) {
    const options: ts.CompilerOptions = { noEmit: true, types: [], erasableSyntaxOnly }
    const program = ts.createProgram(["/app/main.ts"], options, host)
    const codes = ts.getPreEmitDiagnostics(program).map((d) => `TS${d.code}`)
    console.log(`erasableSyntaxOnly: ${erasableSyntaxOnly} →`, codes)
}

