import { spawnSync } from "node:child_process"

const dir = mkdtempSync(join(tmpdir(), "enum-"))
const file = join(dir, "color.ts")
writeFileSync(file, `enum Color { Red, Green }\nconsole.log(Color.Green)`)

const strip = spawnSync(process.execPath, [file], { encoding: "utf8" })
