import ts from "typescript"

const configs = {
    node: { module: "nodenext", target: "es2022", strict: true, verbatimModuleSyntax: true, outDir: "dist" },
    bundler: { module: "esnext", moduleResolution: "bundler", noEmit: true, strict: true },
    typo: { module: "nodnext", strict: true },
}

for (const [name, json] of Object.entries(configs)) {
    const { options, errors } = ts.convertCompilerOptionsFromJson(json, "/app")
    const moduleName = options.module === undefined ? "?" : ts.ModuleKind[options.module]
    const codes = errors.map((e) => `TS${e.code}`)
    console.log(name.padEnd(8), "module:", moduleName.padEnd(9), "xatolar:", codes.length ? codes : "yo'q")
}

type Config = Record<string, unknown>

function modernize(old: Config): Config {
    const next: Config = { ...old }
    if (["node", "node10", "classic"].includes(String(next.moduleResolution))) next.moduleResolution = "bundler"
    if (["amd", "umd", "system", "none"].includes(String(next.module))) next.module = "esnext"
    if (next.target === "es5") next.target = "es2022"
    if (next.esModuleInterop === true) delete next.esModuleInterop       // endi doim yoqilgan

    if (typeof next.baseUrl === "string") {                              // baseUrl olib tashlangan
        const base = next.baseUrl
        const paths = (next.paths ?? {}) as Record<string, string[]>
        next.paths = Object.fromEntries(
            Object.entries(paths).map(([alias, targets]) => [alias, targets.map((t) => `./${base}/${t}`)]),
        )
        delete next.baseUrl
    }
    return next
}

const old: Config = {
    target: "es5", module: "amd", moduleResolution: "node", baseUrl: "src",
    paths: { "@/*": ["*"] }, esModuleInterop: true, strict: true,
}
console.log(JSON.stringify(modernize(old), null, 2))

