import ts from "typescript"

function diagnose(files: Record<string, string>): string[] {
    const options: ts.CompilerOptions = { noEmit: true, types: [], noImplicitAny: true, module: ts.ModuleKind.ESNext, moduleResolution: ts.ModuleResolutionKind.Bundler }
    const host = ts.createCompilerHost(options)
    const { fileExists, readFile, getSourceFile, directoryExists } = host
    host.fileExists = (f) => f in files || fileExists(f)
    host.readFile = (f) => files[f] ?? readFile(f)
    host.directoryExists = (d) => Object.keys(files).some((f) => f.startsWith(d + "/")) || !!directoryExists?.(d)
    host.getSourceFile = (f, lang) => (f in files ? ts.createSourceFile(f, files[f], lang) : getSourceFile(f, lang))
    const roots = Object.keys(files).filter((f) => f.endsWith(".ts"))
    return ts.getPreEmitDiagnostics(ts.createProgram(roots, options, host)).map((d) => `TS${d.code}`)
}

