function diagnose(source: string, options: ts.CompilerOptions): string[] {
    const files: Record<string, string> = {
        "/app/node_modules/@types/node-lite/package.json": '{ "name": "@types/node-lite", "types": "index.d.ts" }',
        "/app/node_modules/@types/node-lite/index.d.ts": "declare const process: { env: Record<string, string | undefined> }",
        "/app/main.ts": source,
    }
    const all: ts.CompilerOptions = { noEmit: true, module: ts.ModuleKind.ESNext, moduleResolution: ts.ModuleResolutionKind.Bundler, typeRoots: ["/app/node_modules/@types"], ...options }
    const host = ts.createCompilerHost(all)
    const { fileExists, readFile, getSourceFile, directoryExists } = host
    host.fileExists = (f) => f in files || fileExists(f)
    host.readFile = (f) => files[f] ?? readFile(f)
    host.directoryExists = (d) => Object.keys(files).some((f) => f.startsWith(d + "/")) || !!directoryExists?.(d)
    host.getSourceFile = (f, lang) => (f in files ? ts.createSourceFile(f, files[f], lang) : getSourceFile(f, lang))
    return ts.getPreEmitDiagnostics(ts.createProgram(["/app/main.ts"], all, host)).map((d) => `TS${d.code}`)
}

