import ts from "typescript"

function diagnose(source: string): string[] {
    const options: ts.CompilerOptions = { noEmit: true, types: [], erasableSyntaxOnly: true, module: ts.ModuleKind.ESNext }
    const host = ts.createCompilerHost(options)
    const getSourceFile = host.getSourceFile
    host.fileExists = (f) => f === "/app/main.ts"
    host.getSourceFile = (f, lang) => (f === "/app/main.ts" ? ts.createSourceFile(f, source, lang) : getSourceFile(f, lang))
    return ts.getPreEmitDiagnostics(ts.createProgram(["/app/main.ts"], options, host)).map((d) => `TS${d.code}`)
}

