import ts from "typescript"

function diagnose(files: Record<string, string>): string[] {
    const options: ts.CompilerOptions = { noEmit: true, types: [], module: ts.ModuleKind.ESNext, moduleResolution: ts.ModuleResolutionKind.Bundler }
    const host = ts.createCompilerHost(options)
    const { getSourceFile, directoryExists } = host
    host.fileExists = (f) => f in files
    host.directoryExists = (d) => Object.keys(files).some((f) => f.startsWith(d + "/")) || !!directoryExists?.(d)
    host.getSourceFile = (f, lang) => (f in files ? ts.createSourceFile(f, files[f], lang) : getSourceFile(f, lang))
    return ts.getPreEmitDiagnostics(ts.createProgram(Object.keys(files), options, host)).map((d) => `TS${d.code}`)
}

const shapes = { "/app/shapes.ts": "export namespace Shapes { export class Circle {} }" }
const use = (code: string) => ({ ...shapes, "/app/main.ts": `import * as m from "./shapes"\n${code}` })

console.log("m.Shapes.Circle →", diagnose(use("export const c = new m.Shapes.Circle()")))
console.log("m.Circle        →", diagnose(use("export const c = new m.Circle()")))

